def get_layer_number(r, c, grid, visited=None):
    """
    Get the layer number for a cell. Layer 0 = outermost (touching different color).
    Each subsequent layer is one more inward.
    """
    if visited is None:
        visited = set()

    if grid[r][c] == 0 or (r, c) in visited:
        return 0

    visited.add((r, c))
    result = 0

    # Check if this is outermost layer (has neighbor with different non-zero color)
    has_different_neighbor = False
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            neighbor = grid[nr][nc]
            if neighbor != 0 and neighbor != grid[r][c]:
                has_different_neighbor = True
                break

    if has_different_neighbor:
        result = 0  # Outermost

        # Find all cells at this layer
        current_cells = set([(r, c)])
        visited_local = set([(r, c)])

        while current_cells:
            layer_cells = 0
            next_cells = set()
            for cr, cc in current_cells:
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if (nr, nc) not in visited_local and grid[nr][nc] == grid[r][c]:
                            visited_local.add((nr, nc))
                            next_cells.add((nr, nc))
            # count cells at this layer
            for cr, cc in current_cells:
                layer_cells += 1
            current_cells = next_cells

        result = 0

    return result

